import json, re, glob, os

pages = sorted(glob.glob("/root/website-redesign/*.html"))
print(f"Scanning {len(pages)} pages for JSON-LD validity...\n")

errors = []
for path in pages:
    with open(path) as f:
        content = f.read()
    name = os.path.basename(path)
    # find all script type="application/ld+json" blocks
    pattern = re.compile(r'<script[^>]*type=["\']application/ld\+json["\'][^>]*>(.*?)</script>', re.DOTALL)
    matches = pattern.findall(content)
    if not matches:
        errors.append(f"{name}: NO JSON-LD FOUND")
        continue
    for i, block in enumerate(matches):
        try:
            data = json.loads(block)
            # basic sanity: must have @context
            if "@context" not in data:
                errors.append(f"{name} block {i+1}: missing @context")
            elif isinstance(data, dict) and "@graph" in data:
                for item in data["@graph"]:
                    if not isinstance(item, dict) or "@type" not in item:
                        errors.append(f"{name} block {i+1}: @graph item missing @type")
            elif isinstance(data, dict) and "@type" not in data:
                errors.append(f"{name} block {i+1}: missing @type")
        except json.JSONDecodeError as e:
            errors.append(f"{name} block {i+1}: JSON PARSE ERROR — {e}")

if errors:
    print("FAILURES:")
    for e in errors:
        print(f"  - {e}")
else:
    print("ALL PAGES: JSON-LD VALID")

# count pages with JSON-LD
valid_count = sum(1 for p in pages if re.search(r'<script[^>]*type=["\']application/ld\+json["\']', open(p).read()))
print(f"\n{pages.__len__()} pages total, {valid_count} with JSON-LD, {pages.__len__() - valid_count} without")
